#!/usr/bin/env bash
# Writes THIRD_PARTY_NOTICES.md: licenses of the npm packages and the
# runtime of the core (backend/scripts/notices.ts) and of the Go modules
# linked into the machine builds it embeds (cmd/<slug> for Linux and
# macOS). The web UI's bundled dependencies are listed in
# web/dist/licenses.md (generated by Vite) and served by the core at
# /licenses.md.
#
#   scripts/notices.sh            regenerate THIRD_PARTY_NOTICES.md
#   scripts/notices.sh --check    fail if it is out of date
set -euo pipefail
cd "$(dirname "$0")/.."
out=THIRD_PARTY_NOTICES.md
tmp=$(mktemp)
trap 'rm -f "$tmp"' EXIT

main=$(go list -m)
slug=$(sed -n 's/^[[:space:]]*Slug = "\(.*\)"$/\1/p' internal/brand/brand.go)
mods=$(for os in linux darwin; do GOOS=$os go list -deps -f '{{with .Module}}{{.Path}}{{end}}' "./cmd/$slug"; done | sort -u | grep -vx "$main" || true)
{
  echo "# Third-party notices"
  echo
  echo "The core is built from backend/ with Bun; its runtime and the npm packages it"
  echo "bundles are listed at the end. The machine builds it embeds (the Go program"
  echo "cmd/$slug, which it runs on Linux and macOS machines) include the following Go"
  echo "modules. The web UI embedded in the core bundles further dependencies; their"
  echo "licenses are in \`licenses.md\` (served at \`/licenses.md\`, generated by"
  echo "\`pnpm -C web build\`)."
  echo "code-server and VS Code extensions are downloaded at runtime, not bundled."
  echo "The web UI's terminal emulator is Ghostty's libghostty-vt (https://github.com/ghostty-org/ghostty, MIT) built as WebAssembly; its license is in licenses.md too, as are those of KaTeX (MIT), Monaco (https://github.com/microsoft/monaco-editor, MIT, with the notices of the code it bundles), the JetBrains Mono font (OFL-1.1), VSCodium's logo (https://github.com/VSCodium/vscodium, MIT; recolored, its VS Code icon) and the AI services' marks of Lobe Icons (https://github.com/lobehub/lobe-icons, MIT; the AI usage plugin's) the UI bundles."
  echo "The core also embeds the unmodified herdr-core executables for Linux and macOS machines (https://github.com/herdrdev/herdr-core, Apache-2.0); release archives carry their license and dependency notices in licenses/herdr-core/."
  echo "The agents embedded in the core carry herdr's agent detection rules (herdr v0.9.5, https://github.com/herdrdev/herdr, Apache-2.0), unchanged; see licenses/herdr-detect/."
  echo "The core also embeds a video encoder for Linux machines, built from FFmpeg (LGPL-2.1-or-later), libvpx, libva, libdrm and nv-codec-headers; see licenses/encoder/ for their licenses and sources."
  echo
  echo "## Go (image/jpeg, adapted in internal/jpegstrip)"
  echo
  echo '```text'
  cat licenses/go/LICENSE
  echo '```'
  for m in $mods; do
    dir=$(go list -m -f '{{.Dir}}' "$m")
    ver=$(go list -m -f '{{.Version}}' "$m")
    lic=$(ls "$dir" | grep -iE '^(licen[cs]e|copying)(\.(md|txt))?$' | head -1 || true)
    echo
    echo "## $m $ver"
    echo
    if [[ -n "$lic" ]]; then
      echo '```text'
      cat "$dir/$lic"
      echo '```'
    else
      echo "No license file found in the module."
    fi
  done
  echo
  (cd backend && bun scripts/notices.ts)
} > "$tmp"

if [[ "${1:-}" == "--check" ]]; then
  if ! cmp -s "$tmp" "$out"; then
    echo "$out is out of date; run scripts/notices.sh"
    exit 1
  fi
  exit 0
fi
cp "$tmp" "$out"
echo "wrote $out ($(echo "$mods" | grep -c . || true) modules)"
